package com.bank.wallet;

import java.math.BigDecimal;
import java.util.logging.*;

public class WalletDemo {
    private static final Logger log = Logger.getLogger("Wallet");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        WalletRepository repo = new WalletRepository();
        repo.open("WAL-RAJESH", "Rajesh Kumar", BigDecimal.ZERO);
        repo.open("WAL-PRIYA", "Priya Sharma", new BigDecimal("5000"));
        Ledger ledger = new Ledger();
        WalletService wallet = new WalletService(repo, ledger,
            new IdempotencyStore(), new LimitService(new BigDecimal("20000")));

        // Top up Rajesh from his bank, with idempotency key
        wallet.topUp("idem-topup-1", "WAL-RAJESH", new BigDecimal("15000"));
        // Retry the SAME top-up (timeout) → must not double-credit
        wallet.topUp("idem-topup-1", "WAL-RAJESH", new BigDecimal("15000"));
        log.info(() -> "Rajesh balance: " + repo.balance("WAL-RAJESH"));

        // P2P transfer Rajesh → Priya (atomic)
        wallet.transfer("idem-p2p-1", "WAL-RAJESH", "WAL-PRIYA", new BigDecimal("5000"));
        log.info(() -> "Rajesh=" + repo.balance("WAL-RAJESH") + " Priya=" + repo.balance("WAL-PRIYA"));

        // Exceed daily limit → rejected
        try {
            wallet.transfer("idem-p2p-2", "WAL-RAJESH", "WAL-PRIYA", new BigDecimal("18000"));
        } catch (IllegalStateException e) {
            log.warning(() -> "Blocked: " + e.getMessage());
        }

        ledger.print(log);
    }
}

