package com.bank.wallet;

import java.math.BigDecimal;
import java.util.*;

public class WalletRepository {
    static class Row { String holder; BigDecimal balance; long version;
        Row(String h, BigDecimal b){holder=h;balance=b;version=0;} }
    private final Map<String, Row> wallets = new HashMap<>();

    public void open(String id, String holder, BigDecimal opening) {
        wallets.put(id, new Row(holder, opening));
    }
    public BigDecimal balance(String id) { return wallets.get(id).balance; }
    public long version(String id) { return wallets.get(id).version; }

    // conditional debit (optimistic lock): fails if version changed or insufficient
    public synchronized boolean debit(String id, BigDecimal amount, long expectedVersion) {
        Row r = wallets.get(id);
        if (r.version != expectedVersion || r.balance.compareTo(amount) < 0) return false;
        r.balance = r.balance.subtract(amount);
        r.version++;
        return true;
    }
    public synchronized void credit(String id, BigDecimal amount) {
        Row r = wallets.get(id);
        r.balance = r.balance.add(amount);
        r.version++;
    }
}
