package com.bank.wallet;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

public class Ledger {
    public record Entry(String txnId, String wallet, String direction, BigDecimal amount, String type) {
        BigDecimal signed() { return direction.equals("CREDIT") ? amount : amount.negate(); }
    }
    private final List<Entry> entries = new ArrayList<>();

    public void post(String txnId, String from, String to, BigDecimal amount, String type) {
        entries.add(new Entry(txnId, from, "DEBIT", amount, type));
        entries.add(new Entry(txnId, to, "CREDIT", amount, type));
    }
    public void print(Logger log) {
        log.info("Wallet ledger (append-only, double-entry):");
        entries.forEach(e -> log.info(() -> "  " + e.type() + " " + e.direction()
            + " " + e.wallet() + " Rs." + e.amount()));
        BigDecimal sum = entries.stream().map(Entry::signed).reduce(BigDecimal.ZERO, BigDecimal::add);
        log.info(() -> "Ledger balances to zero: " + (sum.compareTo(BigDecimal.ZERO) == 0));
    }
}
