package com.bank.wallet;

import java.math.BigDecimal;
import java.util.*;

public class LimitService {
    private final BigDecimal dailyLimit;
    private final Map<String, BigDecimal> spentToday = new HashMap<>();

    public LimitService(BigDecimal dailyLimit) { this.dailyLimit = dailyLimit; }

    public void checkAndAdd(String wallet, BigDecimal amount) {
        BigDecimal spent = spentToday.getOrDefault(wallet, BigDecimal.ZERO);
        if (spent.add(amount).compareTo(dailyLimit) > 0)
            throw new IllegalStateException("daily limit Rs." + dailyLimit + " exceeded for " + wallet);
        spentToday.put(wallet, spent.add(amount));
    }
}
