// ─── File: WalletService.java ───
package com.bank.wallet;

import java.math.BigDecimal;
import java.util.logging.*;

public class WalletService {
    private static final Logger log = Logger.getLogger("Wallet");
    private final WalletRepository repo;
    private final Ledger ledger;
    private final IdempotencyStore idem;
    private final LimitService limits;

    public WalletService(WalletRepository repo, Ledger ledger, IdempotencyStore idem, LimitService limits) {
            this.repo = repo;
            this.ledger = ledger
            this.idem = idem
            this.limits = limits;
    }

    public void topUp(String idemKey, String wallet, BigDecimal amount) {
        if (idem.seen(idemKey)) { log.warning(() -> "Idempotent top-up " + idemKey); return; }
        ledger.post(idemKey, "FUNDING-BANK", wallet, amount, "TOPUP");
        repo.credit(wallet, amount);
        idem.record(idemKey);
        log.info(() -> "Topped up " + wallet + " Rs." + amount);
    }

    // atomic P2P transfer with idempotency + optimistic lock + limit
    public synchronized void transfer(String idemKey, String from, String to, BigDecimal amount) {
        if (idem.seen(idemKey)) { log.warning(() -> "Idempotent transfer " + idemKey); return; }
        limits.checkAndAdd(from, amount);                 // enforce daily limit
        long v = repo.version(from);
        if (!repo.debit(from, amount, v))                 // conditional debit
            throw new IllegalStateException("debit failed (insufficient or concurrent) " + from);
        repo.credit(to, amount);                          // both or neither
        ledger.post(idemKey, from, to, amount, "TRANSFER");
        idem.record(idemKey);
        log.info(() -> "Transferred Rs." + amount + " " + from + " -> " + to);
    }

    public void refund(String idemKey, String payee, String payer, BigDecimal amount) {
        if (idem.seen(idemKey)) return;
        repo.debit(payee, amount, repo.version(payee));
        repo.credit(payer, amount);
        ledger.post(idemKey, payee, payer, amount, "REFUND");
        idem.record(idemKey);
        log.info(() -> "Refunded Rs." + amount);
    }
}
